const runtime = await mkdtemp(join(tmpdir(), 'husun-render-'));
const files = JSON.parse(gunzipSync(Buffer.from(archive, 'base64')).toString('utf8'));
for (const [name, content] of Object.entries(files)) {
  const path = join(runtime, name);
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, Buffer.from(content, 'base64'));
}
await import(pathToFileURL(join(runtime, 'app.js')).href);
